VNS_rd.Properties.VariableNames{6}='Ba5_A';
VNS_rd.Properties.VariableNames{7}='Ba6_A';
VNS_rd.Properties.VariableNames{8}='Ba7_A';
P1=timerange('2016-01-01','2021-01-01');
P2=timerange('2021-01-01','2026-01-01');
%VNS_rd2.Properties.VariableNames{1}='BB';
%%
for i=2:length(names_rd)-3
  namesx=strcat(names_rd{i},'_VNS_rd2');
VNS_rd.(names_rd{i})(P2)=VNS_rd.(namesx)(P2);
end
%%
datevec(VNS_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(VNS_rd.Time(end)) % end in 2023 March %[output:0c280ed0]
